          and t.tgname not in('agreement_voice_message_guard_v1','agreement_voice_link_guard_v1','agreement_voice_asset_guard_v1','agreement_voice_storage_guard_v1')),
      'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p
