    ('public.rpc_agreement_voice_upload_service_v1(uuid,uuid,text,uuid,integer,uuid,jsonb)','aebb8132f2500415b2daded197e57975'),
    ('public.rpc_read_agreement_messages_page_v2(uuid,uuid,integer,timestamptz,uuid)','c0ae8862bb86be54834227c10d2aef89'),
    ('public.rpc_read_agreement_message_window_v2(uuid,uuid,uuid,integer,integer)','e16aeb18144c44a8baa4aebaf420944c'),
    ('private.agreement_messages_v1_view(jsonb,text)','4a2065e1b0c27894f4e2dcc352d7fb59'),
    ('private.agreement_voice_surface_v1()','b697d12234198c95815257d7ce73f147')
