  select jsonb_agg(to_jsonb(p) order by policyname) into before_storage_policies from pg_policies p where schemaname='storage' and tablename='objects' and policyname is distinct from 'agreement_voice_no_client_v1';
  rewritten:=array[to_regprocedure('private.closure_redaction_relations_v5()'),to_regprocedure('private.closure_redaction_scope_v5(text)'),to_regprocedure('private.closure_redaction_patch_v5(text,jsonb,uuid,uuid)'),to_regprocedure('private.closure_blockers_v5(uuid)'),to_regprocedure('public.rpc_start_account_closure_execution(uuid,uuid,integer,uuid,text)'),to_regprocedure('private.support_reference_v5(uuid,jsonb)'),to_regprocedure('private.data_export_snapshot(uuid,uuid,jsonb,timestamptz)'),to_regprocedure('private.data_export_dataset_catalog()'),to_regprocedure('private.data_export_policy_binding()'),to_regprocedure('private.closure_source_digest_v5()'),to_regprocedure('private.closure_erasure_program_digest_v5()'),to_regprocedure('public.rpc_read_agreement_messages_page_v1(uuid,uuid,integer,timestamptz,uuid)'),to_regprocedure('public.rpc_read_agreement_message_window_v1(uuid,uuid,uuid,integer,integer)')]::oid[];
  if cardinality(rewritten)<>13 or array_position(rewritten,null) is not null then raise exception 'VOICE_B1_REVERT_REWRITTEN_ROSTER' using errcode='55000';end if;
  voice_functions:=array[to_regprocedure('private.agreement_voice_key_v1(uuid)'),to_regprocedure('private.agreement_voice_context_v1(uuid,uuid,integer,boolean)'),to_regprocedure('private.agreement_voice_document_v1(private.agreement_voice_uploads_v1)'),to_regprocedure('private.agreement_voice_transfer_v1(private.agreement_voice_uploads_v1)'),to_regprocedure('private.agreement_voice_message_guard_v1()'),to_regprocedure('private.agreement_voice_link_guard_v1()'),to_regprocedure('private.agreement_voice_asset_guard_v1()'),to_regprocedure('private.agreement_voice_storage_guard_v1()'),to_regprocedure('public.rpc_send_agreement_voice_message_v1(uuid,uuid,integer,text,uuid)'),to_regprocedure('public.rpc_agreement_voice_read_service_v1(uuid,uuid,uuid,uuid,uuid)'),to_regprocedure('public.rpc_agreement_voice_upload_service_v1(uuid,uuid,text,uuid,integer,uuid,jsonb)'),to_regprocedure('public.rpc_read_agreement_messages_page_v2(uuid,uuid,integer,timestamptz,uuid)'),to_regprocedure('public.rpc_read_agreement_message_window_v2(uuid,uuid,uuid,integer,integer)'),to_regprocedure('private.agreement_messages_v1_view(jsonb,text)'),to_regprocedure('private.agreement_voice_surface_v1()')]::oid[];
