  -- 1. The pre-image definitions (the 13 rewritten functions, then the readiness function with the target digest).
  -- private.closure_redaction_relations_v5()
  execute $voice_b1_restore_01$CREATE OR REPLACE FUNCTION private.closure_redaction_relations_v5()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select array[
