"qaClassifications", "fields": ["createdAt", "id", "materiality", "needId", "needRevision", "outcome", "questionId", "state", "type"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "qaCommands", "fields": ["createdAt", "questionId", "status", "type"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.actor_account_id=REQUEST_ACCOUNT"}, {"key": "ownedMediaAssets", "fields": ["byteSize", "bytesIncluded", "conversationId", "createdAt", "height", "id", "profileId", "scope", "selected", "state", "width"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "testAdmission", "fields": ["admittedAt", "retiredAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "testAllocations", "fields": ["allocatedMaximumMicrousd", "createdAt", "kind", "measuredProviderCharge", "settledAt", "settledMicrousd", "settlementBasis"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "closureRequests", "fields": ["closedAt", "id", "preparedAt", "requestedAt", "revision", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "closureExecution", "fields": ["closedAt", "requestId", "requestedAt", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "closureActions", "fields": ["dispatchedAt", "evidence", "kind", "state", "verifiedAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownGroupMessages", "fields": ["id", "groupId", "body", "createdAt"], "dataClass": "AGREEMENT_MESSAGES", "ownershipFilter": "t.sender_account_id=REQUEST_ACCOUNT"}, {"key": "ownGroupMemberships", "fields": ["groupId", "agreementId", "joinedAt", "endedAt"], "dataClass": "AGREEMENT_CORE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownLocationSnapshots", "fields": ["agreementId", "agreementVersion", "latitude", "longitude", "accuracyMeters", "capturedAt", "sharedAt"], "dataClass": "NEED_SENSITIVE", "ownershipFilter": "t.actor_account_id=REQUEST_ACCOUNT and a.worker_account_id=REQUEST_ACCOUNT"}, {"key": "ownLocationCommands", "fields": ["agreementId", "agreementVersion", "kind", "state", "createdAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.actor_account_id=REQUEST_ACCOUNT and REQUEST_ACCOUNT in(a.requester_account_id,a.worker_account_id)"}, {"key": "ownAcceptedTaskMedia", "fields": ["agreementId", "agreementVersion", "needId", "needRevision", "state", "assets", "capturedAt", "bytesIncluded"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and a.requester_account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportCases", "fields": ["id", "caseNumber", "channel", "topic", "title", "desiredOutcome", "context", "status", "revision", "createdAt", "updatedAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportEvents", "fields": ["id", "caseId", "sequence", "kind", "authorRole", "body", "decisionId", "appealId", "createdAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportDecisions", "fields": ["id", "caseId", "caseRevision", "outcome", "reasonCode", "explanation", "effect", "evidenceIds", "priorDecisionId", "createdAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportAppeals", "fields": ["id", "caseId", "decisionId", "status", "decisionResultId", "createdAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportEvidence", "fields": ["id", "caseId", "eventId", "reference", "createdAt", "bytesIncluded"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.submitted_by_account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportComma